/* Ocean Surface — design tokens.
   Single source of visual truth. Ocean's OWN identity: a near-black stage
   with the OCEAN depth ramp (deep indigo → bright aqua, from the TUI splash
   banner), Poppins UI type, product register — brand energy only at identity
   + state moments; everything else restrained. Spec:
   docs/OCEAN_WEB_SURFACE_DESIGN.md — read it before adding ANY color literal
   outside this file. */

/* Poppins — vendored woff2 (public/fonts/, copied beside the CSS in dist).
   Relative url() so the same file works in the web dist root AND the Chrome
   extension's dist/ (sidepanel.html links dist/tokens.css; fonts are copied
   to extension/dist/fonts by scripts/build-extension.sh). */
@font-face {
  font-family: 'Poppins';
  src: url('fonts/Poppins-Regular.woff2') format('woff2');
  font-weight: 400;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: 'Poppins';
  src: url('fonts/Poppins-Medium.woff2') format('woff2');
  font-weight: 500;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: 'Poppins';
  src: url('fonts/Poppins-SemiBold.woff2') format('woff2');
  font-weight: 600;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: 'Poppins';
  src: url('fonts/Poppins-Bold.woff2') format('woff2');
  font-weight: 700;
  font-style: normal;
  font-display: swap;
}

:root {
  /* ── Surfaces ─────────────────────────────────────────────────── */
  --bg: #060606;            /* page */
  --bg-raised: #0A0A0A;     /* bars, panels, drawers */
  --bg-elevated: #141414;   /* cards, inputs, chips, wells */
  --bg-hover: #1B1C21;      /* hover fill on elevated surfaces */
  --bg-well: #23252B;       /* data wells: code, diff, transcripts */

  /* ── Text ─────────────────────────────────────────────────────── */
  --fg: #FAFCFF;            /* headings, primary content */
  --fg-2: #B8B9BB;          /* body secondary */
  --fg-3: #909098;          /* labels, metadata */
  --fg-4: #5A5C63;          /* disabled only */

  /* ── Brand — the OCEAN depth ramp ─────────────────────────────── */
  /* Source of truth: the TUI splash banner (ocean-os ocean-tui/src/splash.rs),
     xterm-256 indices 17→19→25→31→38→44→50→87. Abyss to sunlit surface.
     The ramp paints IDENTITY (wordmark, landing banner, data fills); the
     interactive accent is the working cyan from its bright end. */
  --ocean-1: #00005F;
  --ocean-2: #0000AF;
  --ocean-3: #005FAF;
  --ocean-4: #0087AF;
  --ocean-5: #00AFD7;
  --ocean-6: #00D7D7;
  --ocean-7: #00FFD7;
  --ocean-8: #5FFFFF;
  --accent: var(--ocean-6);                /* interactive accent on dark */
  --accent-bright: var(--ocean-7);         /* hot highlight, live moments */
  --accent-deep: var(--ocean-4);           /* depth tone, gradients only */
  --fg-on-accent: #03181A;                 /* ink on accent fills */
  --gradient: linear-gradient(180deg, var(--ocean-6), var(--ocean-4)); /* data fills (charts), never buttons */
  --accent-soft: rgba(0, 215, 215, 0.12);  /* tinted fills */
  --accent-ring: rgba(0, 215, 215, 0.45);  /* focus ring */

  /* ── Brand — the Ocean badge (the circular mark) ─────────────── */
  /* Source of truth: docs/assets/ocean-logo-circular-neumorphic-reference.png,
     pixel-sampled 2026-07-08. The badge is MUTED — matte turquoise→blue on a
     coin face darker than the page — not the neon working ramp above. These
     tokens exist only for the badge (icons.rs WaveBadge); nothing else may
     take them. */
  --badge-face: #020203;                   /* coin face — darker than --bg */
  --badge-rim: rgba(148, 156, 160, 0.22);  /* rim relief edge */
  /* Six-strata depth ramp: sunlit aqua surface → indigo abyss. Muted,
     not the neon working ramp. Per-band hi/lo derive via color-mix in the
     wave-badge rules (transcript.css). */
  --badge-b1: #4fd8c0;                      /* aqua surface */
  --badge-b2: #2bb4a6;                      /* teal */
  --badge-b3: #1f95b8;                      /* cyan-blue */
  --badge-b4: #2170be;                      /* blue */
  --badge-b5: #2453bc;                      /* deep blue */
  --badge-b6: #1a2f8e;                      /* indigo abyss */
  --badge-foam: #eafcff;                    /* surface glint / whitecap */
  --badge-split: #05101f;                   /* dark longitudinal split */
  --badge-gloss: #cff4ff;                   /* top specular sheen (glass) */

  /* ── Water reveal — the scene water gradient, crest, and tint ─── */
  --water-hi: #2ea6c6;
  --water-mid: #1c63b0;
  --water-lo: #0a1642;
  --water-crest: var(--badge-foam);
  --water-crest-soft: #bfeff8;
  --water-tint: #0b2048;

  /* Wordmark / reveal type + slow letter shimmer (solid fills, never
     gradient-clip text). Shimmer brightens each letter toward foam. */
  --wm-font: 'Poppins', system-ui, -apple-system, 'Segoe UI', sans-serif;
  --letter-shimmer: color-mix(in srgb, var(--badge-foam) 55%, var(--ocean-8));

  /* ── Status ───────────────────────────────────────────────────── */
  --ok: #1ED760;    --ok-soft: rgba(30, 215, 96, 0.12);
  --err: #FF4D67;   --err-soft: rgba(255, 77, 103, 0.12);
  --warn: #FFB224;  --warn-soft: rgba(255, 178, 36, 0.12);
  --info: #6AA6FF;  --info-soft: rgba(106, 166, 255, 0.12);
  --running: var(--warn);

  /* ── Borders ──────────────────────────────────────────────────── */
  --border-subtle: rgba(255, 255, 255, 0.06);
  --border: rgba(255, 255, 255, 0.10);
  --border-strong: rgba(255, 255, 255, 0.20);

  /* ── Type ─────────────────────────────────────────────────────── */
  --font: 'Poppins', system-ui, -apple-system, 'Segoe UI', sans-serif;
  --mono: ui-monospace, 'SF Mono', SFMono-Regular, Menlo, monospace;

  /* ── Radii — pill is geometry, never chrome ───────────────────── */
  --radius-sm: 4px;
  --radius: 6px;
  --radius-lg: 10px;
  --radius-pill: 999px;

  /* ── Shadows / glow ───────────────────────────────────────────── */
  --shadow-sm: 0 2px 8px rgba(0, 0, 0, 0.40);
  --shadow-md: 0 8px 24px rgba(0, 0, 0, 0.55);
  --shadow-lg: 0 24px 64px rgba(0, 0, 0, 0.65);
  --glow-brand: 0 0 32px rgba(0, 215, 215, 0.28);

  /* ── Material — molded from the digital ocean ─────────────────── */
  /* One overhead light source. RAISED surfaces catch a top-edge
     specular and cast a dark drop below; CARVED wells fall away into
     darker water. Elevation REPLACES borders: an element takes the
     border recipe or the elevation recipe, never a 1px border plus a
     big-blur shadow. Agent cognition is bioluminescence: state hooks
     drive the glow tokens. */
  --specular: rgba(255, 255, 255, 0.08);       /* top-edge light, raised */
  --specular-soft: rgba(255, 255, 255, 0.05);
  --specular-live: rgba(95, 255, 255, 0.16);   /* aqua specular, live/active */
  /* Corner-shading sheen: light catches the top of a rounded surface and
     falls to shade at the bottom — layered UNDER a surface color:
